<script setup lang="ts">
import { nextTick,onBeforeUnmount,ref } from 'vue'
const opened=ref(false),dialog=ref<HTMLDialogElement>(),closeButton=ref<HTMLButtonElement>()
let returnFocus:HTMLElement|null=null
async function open(){returnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;opened.value=true;await nextTick();dialog.value?.showModal?.();closeButton.value?.focus()}
function close(){dialog.value?.close?.();opened.value=false;returnFocus?.focus()}
